// Page through collected_jobs honoring the saved filters.
const base = $env.TALENTBRIDGE_BASE_URL;
const secret = $env.N8N_WEBHOOK_SECRET;
const job = $input.first().json.job;
const filters = job.filters || {};

const params = new URLSearchParams();
if (filters.status && filters.status !== 'all') params.set('status', filters.status);
params.set('limit', '500');

const rows = [];
let page = 0;
const CAP = 100000;
while (rows.length < CAP) {
  const res = await this.helpers.httpRequest({
    method: 'GET',
    url: `${base}/api/public/n8n/collected-jobs?${params.toString()}`,
    headers: { 'x-n8n-secret': secret },
    json: true,
  });
  const batch = res.jobs || [];
  if (batch.length === 0) break;
  rows.push(...batch);
  if (batch.length < 500) break;
  page += 1;
  // collected-jobs endpoint returns latest N — break out; consumers can extend with proper pagination.
  break;
}

return [{ json: { job, rows } }];

// Build CSV or XLSX in memory.
const { job, rows } = $input.first().json;
const format = job.format;
const cols = ['job_title','company_name','location','skills','source','job_url','posted_date','status','created_at'];
const toCell = (v) => v == null ? '' : Array.isArray(v) ? v.join('|') : String(v);

let buffer; let mime; let ext;
if (format === 'csv') {
  const esc = (s) => '"' + String(s).replace(/"/g, '""') + '"';
  const lines = [cols.join(',')];
  for (const r of rows) lines.push(cols.map((c) => esc(toCell(r[c]))).join(','));
  buffer = Buffer.from('\uFEFF' + lines.join('\n'), 'utf8');
  mime = 'text/csv';
  ext = 'csv';
} else {
  const XLSX = require('xlsx');
  const data = rows.map((r) => Object.fromEntries(cols.map((c) => [c, toCell(r[c])])));
  const ws = XLSX.utils.json_to_sheet(data, { header: cols });
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, 'Collected Jobs');
  buffer = XLSX.write(wb, { bookType: 'xlsx', type: 'buffer' });
  mime = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
  ext = 'xlsx';
}

const filePath = `${job.consultancy_id}/${job.id}.${ext}`;
return [{
  binary: { file: await this.helpers.prepareBinaryData(buffer, filePath, mime) },
  json: { job, file_path: filePath, row_count: rows.length, mime }
}];
